import { useState } from 'react';
import './App.css';
// All CSS is now inlined for self-contained execution

// Main App Component
const App = () => {
  // State to control sidebar visibility
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Mock data for food categories and items
  const foodCategories = [
    {
      id: 'pizzas',
      name: 'Breakfast',
      items: [
        { id: 'pizza1', name: 'Dosa', price: 50, image: 'https://imgs.search.brave.com/hoHdqTYHbd9LbL7CigWUK2393waiW0R926MWrwg3XRM/rs:fit:860:0:0:0/g:ce/aHR0cHM6Ly9zdGF0/aWMudmVjdGVlenku/Y29tL3N5c3RlbS9y/ZXNvdXJjZXMvdGh1/bWJuYWlscy8wNjUv/NDA4LzQxNC9zbWFs/bC92aWJyYW50LWNy/aXNweS1kb3NhLXBh/aXJlZC13aXRoLWNy/ZWFteS1zZW1peWEt/a2hlZXItZm9yLWEt/Zmxhdm9yZnVsLW1l/YWwtcGhvdG8uanBn' },
        { id: 'pizza2', name: 'Masala Dosa', price: 70, image: 'https://imgs.search.brave.com/bWh1uUgB8yxLxI-W0Z0bjz-JxaITlu9w0f8HsqbOh8w/rs:fit:860:0:0:0/g:ce/aHR0cHM6Ly93d3cu/dmVncmVjaXBlc29m/aW5kaWEuY29tL3dw/LWNvbnRlbnQvdXBs/b2Fkcy8yMDIxLzA2/L21hc2FsYS1kb3Nh/LTItMjgweDI4MC5q/cGc' },
        { id: 'pizza3', name: 'Idli', price: 40, image: 'https://imgs.search.brave.com/Bkat8tQ1ylcLUuSrNRaQha5HUJwWSE5uWXCS_AE4Fd0/rs:fit:860:0:0:0/g:ce/aHR0cHM6Ly9zdGF0/aWMudmVjdGVlenku/Y29tL3N5c3RlbS9y/ZXNvdXJjZXMvdGh1/bWJuYWlscy8wMTEv/Mzg2LzE1MS9zbWFs/bC9pZGxpLXNhbWJh/ci1zdGVhbWVkLWR1/bXBsaW5ncy13aXRo/LXNhdXNlcy1vbi10/YWJsZS1waG90by5q/cGc' },
        { id: 'pizza4', name: 'Medu wada', price: 50, image: 'https://imgs.search.brave.com/4BZJFJRODgG4ZfXyt8FmqvgtIA6lydOK_yUA90BgQd8/rs:fit:860:0:0:0/g:ce/aHR0cHM6Ly9pbWFn/ZS5zaHV0dGVyc3Rv/Y2suY29tL2ltYWdl/LXBob3RvL21lZHUt/d2FkYS1zYW1iaGFy/LWNvY29udXQtY2h1/dG5leS0yNjBudy0x/NDUxNTA0NjA5Lmpw/Zw' },
        { id: 'pizza5', name: 'Idli wada', price: 45, image: 'https://placehold.co/300x200/FF5733/FFFFFF?text=Hawaiian' },
      ],
    },
    {
      id: 'burgers',
      name: 'Lunch',
      items: [
        { id: 'burger1', name: 'Thali', price: 150, image: 'https://placehold.co/300x200/FFC300/333333?text=Classic+Burger' },
        { id: 'burger2', name: 'Chapati', price: 10, image: 'https://placehold.co/300x200/C70039/FFFFFF?text=Cheeseburger' },
        { id: 'burger3', name: 'mix veg', price: 50, image: 'https://placehold.co/300x200/FF5733/FFFFFF?text=Spicy+Chicken' },
        { id: 'burger4', name: 'paneer', price: 70, image: 'https://placehold.co/300x200/DAF7A6/333333?text=Veggie+Burger' },
      ],
    },
    {
      id: 'desserts',
      name: 'Chinese',
      items: [
        { id: 'dessert1', name: 'Noodles', price: 50, image: 'https://placehold.co/300x200/6A050B/FFFFFF?text=Lava+Cake' },
        { id: 'dessert2', name: 'Fried Rice', price: 50, image: 'https://placehold.co/300x200/FFC300/333333?text=Cheesecake' },
        { id: 'dessert3', name: 'Manchurian', price: 30, image: 'https://placehold.co/300x200/FF5733/FFFFFF?text=Sundae' },
      ],
    },
  ];

  // State to manage cart items (simple example)
  const [cartItems, setCartItems] = useState({});

  // Function to update item quantity in cart
  const updateQuantity = (itemId, newQuantity) => {
    setCartItems(prevItems => {
      const updatedItems = { ...prevItems };
      if (newQuantity <= 0) {
        delete updatedItems[itemId]; // Remove if quantity is 0 or less
      } else {
        updatedItems[itemId] = newQuantity;
      }
      return updatedItems;
    });
  };

  // Calculate total items in cart for display
  const totalCartItems = Object.values(cartItems).reduce((sum, qty) => sum + qty, 0);

  // Profile Icon Component
  const ProfileIcon = () => (
    <div className="profile-icon-container">
      {/* User icon - using inline SVG for simplicity and consistency */}
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="currentColor"
        className="profile-icon-svg"
      >
        <path
          fillRule="evenodd"
          d="M7.5 6a4.5 4.5 0 1 1 9 0a4.5 4.5 0 0 1-9 0ZM3.751 20.105a8.25 8.25 0 0 1 16.498 0 .75.75 0 0 1-.437.695A18.683 18.683 0 0 1 12 22.5c-2.786 0-5.433-.608-7.812-1.7a.75.75 0 0 1-.437-.695Z"
          clipRule="evenodd"
        />
      </svg>
      {/* Tooltip/Dropdown for "View Profile" */}
      <div className="profile-tooltip">
        <a href="#" className="profile-tooltip-link">
          View Profile
        </a>
      </div>
    </div>
  );

  // Header Component
  const Header = ({ toggleSidebar }) => (
    <header className="app-header">
      <div className="header-content">
        {/* Hamburger Icon for mobile/tablet */}
        <button className="hamburger-menu" onClick={toggleSidebar}>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={2}
            stroke="currentColor"
            className="hamburger-icon"
          >
            <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
          </svg>
        </button>

        {/* Website Name/Logo */}
        <h1 className="app-logo">
          Hunger Hub
        </h1>
        {/* Search Bar */}
        <div className="search-bar-container">
          <input
            type="text"
            placeholder="Search for food..."
            className="search-input"
          />
          {/* Search Icon */}
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={2}
            stroke="currentColor"
            className="search-icon"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z"
            />
          </svg>
        </div>
      </div>
      {/* Profile Icon */}
      <ProfileIcon />
    </header>
  );

  // Sidebar Component
  const Sidebar = ({ isSidebarOpen, closeSidebar }) => (
    <>
      <aside className={`app-sidebar ${isSidebarOpen ? 'sidebar-open' : ''}`}>
        <div className="sidebar-header">
          <h2 className="sidebar-title">Menu</h2> {/* Changed from Explore to Menu */}
          <button className="sidebar-close-button" onClick={closeSidebar}>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth={2}
              stroke="currentColor"
              className="sidebar-close-icon"
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18 18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
        <nav>
          <ul>
            <li className="sidebar-list-item">
              <a
                href="#"
                className="sidebar-link"
                onClick={closeSidebar} // Close sidebar on link click
              >
                {/* Category Icon */}
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                  strokeWidth={2}
                  stroke="currentColor"
                  className="sidebar-icon orange-icon"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M9.53 16.122a3 3 0 0 0-5.78 1.128 2.25 2.25 0 0 1-2.494-2.478c.357-1.452-.364-2.891-1.995-3.658L1.1 9.874l4.26-.96a4.5 4.5 0 0 0 2.433-4.373C7.75 2.901 9.663 1.5 12 1.5s4.25 1.401 4.507 3.001a4.5 4.5 0 0 0 2.433 4.373l4.26.96-1.64 1.64a2.25 2.25 0 0 1-2.494 2.478 3 3 0 0 0-5.78-1.128 3 3 0 0 0-5.78 1.128Z"
                  />
                </svg>
                <span>Categories</span>
              </a>
            </li>
            <li className="sidebar-list-item">
              <a
                href="#"
                className="sidebar-link"
                onClick={closeSidebar} // Close sidebar on link click
              >
                {/* Heart Icon */}
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 24 24"
                  fill="currentColor"
                  className="sidebar-icon red-icon"
                >
                  <path d="m11.645 20.917-7.397-7.397 1.414-1.414L12 18.12l5.94-5.94 1.414 1.414-7.398 7.397Z" />
                  <path d="M12 6.042A3.5 3.5 0 0 0 8.5 2.5a3.5 3.5 0 0 0-3.5 3.5v1.5A3.5 3.5 0 0 0 8.5 11h3.5v7.5l7.397-7.397-1.416-1.414L12 15.12V6.042Z" />
                </svg>
                <span>Favorite List</span>
              </a>
            </li>
          </ul>
        </nav>
        {/* Cart Option and Proceed to Pay button at the bottom */}
        <div className="cart-payment-section">
          <a
            href="#"
            className="cart-button"
            onClick={closeSidebar} // Close sidebar on link click
          >
            {/* Shopping Cart Icon */}
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth={2}
              stroke="currentColor"
              className="cart-icon-svg"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M2.25 3h1.386c.51 0 .955.343 1.023.828L5.58 15.322a2.25 2.25 0 0 0 2.247 2.179H16.25a2.25 2.25 0 0 0 2.247-2.179L21.58 6.5H3.257M15 12h6m-3 3v-6"
              />
            </svg>
            <span>Cart</span>
            {totalCartItems > 0 && (
              <span className="cart-item-count animate-bounce-slow">
                {totalCartItems}
              </span>
            )}
          </a>
          {totalCartItems > 0 && ( // Only show "Proceed to Pay" if items are in cart
            <button
              onClick={() => {
                alert('Proceeding to payment! (This is a placeholder action)');
                closeSidebar(); // Close sidebar after action
              }}
              className="proceed-to-pay-button"
            >
              {/* Payment Icon */}
              <svg
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
                strokeWidth={2}
                stroke="currentColor"
                className="payment-icon-svg"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  d="M2.25 8.25h19.5M2.25 9h19.5m-16.5 5.25h6m-6 2.25h3m-3.75 3.75h15.375a2.25 2.25 0 0 0 2.25-2.25V6.75A2.25 2.25 0 0 0 19.5 4.5H4.5A2.25 2.25 0 0 0 2.25 6.75v10.5A2.25 2.25 0 0 0 4.5 19.5Z"
                />
              </svg>
              <span>Proceed to Pay</span>
            </button>
          )}
        </div>
      </aside>
      {isSidebarOpen && <div className="sidebar-overlay" onClick={closeSidebar}></div>}
    </>
  );

  // Food Card Component
  const FoodCard = ({ item, updateQuantity, quantityInCart }) => {
    return (
      <div className="food-card">
        <img
          src={item.image}
          alt={item.name}
          className="food-card-image"
          onError={(e) => {
            e.target.onerror = null; // prevents infinite loop
            e.target.src = `https://placehold.co/300x200/CCCCCC/333333?text=Image+Error`; // Fallback image
          }}
        />
        <div className="food-card-content">
          <h3 className="food-card-name">{item.name}</h3>
          <p className="food-card-price">₹{item.price.toFixed(2)}</p>
          <div className="quantity-controls">
            <button
              onClick={() => updateQuantity(item.id, quantityInCart - 1)}
              className="quantity-button minus-button"
            >
              -
            </button>
            <span className="quantity-display">
              {quantityInCart}
            </span>
            <button
              onClick={() => updateQuantity(item.id, quantityInCart + 1)}
              className="quantity-button plus-button"
            >
              +
            </button>
          </div>
        </div>
      </div>
    );
  };

  // Food Section Component (for horizontal scrolling)
  const FoodSection = ({ category, updateQuantity, cartItems }) => (
    <section className="food-section">
      <h2 className="food-section-title">
        {category.name}
      </h2>
      <div className="food-items-container scrollbar-hide">
        {category.items.map((item) => (
          <FoodCard
            key={item.id}
            item={item}
            updateQuantity={updateQuantity}
            quantityInCart={cartItems[item.id] || 0}
          />
        ))}
      </div>
    </section>
  );

  return (
    <div className="app-container">
      {/* Font Inter CDN */}
      <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet" />


      <Header toggleSidebar={() => setIsSidebarOpen(true)} />
      <div className="main-content-area">
        <Sidebar isSidebarOpen={isSidebarOpen} closeSidebar={() => setIsSidebarOpen(false)} />
        <main className="main-food-display">
          {foodCategories.map((category) => (
            <FoodSection
              key={category.id}
              category={category}
              updateQuantity={updateQuantity}
              cartItems={cartItems}
            />
          ))}
        </main>
      </div>
    </div>
  );
};

export default App;
